/usr/bin/bash -lc "python - <<'PY'
import openpyxl,json,datetime
from pathlib import Path
for path in Path('candidates').glob('*.xlsx'):
 w=openpyxl.load_workbook(path); data={}
 for s in w:
  data[s.title]=[{ 'row':r, 'cells':{s.cell(1,c).value:(v.isoformat() if isinstance(v,(datetime.datetime,datetime.date)) else v) for c,v in enumerate(vals,1) if v is not None}} for r,vals in enumerate(s.iter_rows(min_row=2,values_only=True),2)]
 Path('output/grade/'+path.stem+'_read.json').write_text(json.dumps(data,indent=2,ensure_ascii=False))
 print(path.name,[(s.title,s.max_row,s.max_column) for s in w])
PY"

